  .price-card.custom .billed-text { color: #94a3b8; }
  .price-card.custom .feature-text { color: #cbd5e1; }
  .price-card.custom .icon-check { color: var(--blue-200); }
  .price-card.custom .feature-text strong { color: #fff; }

  /* Plan Header - flex layout for name + badge */
  .plan-header {
