    font-size: 1.25rem;
    font-weight: 900;
    letter-spacing: -0.03em;
    margin: 0;
  }

  /* Badge - inline next to plan name */
  .plan-badge {
    padding: 5px 10px;
    border-radius: 100px;
    font-size: 0.65rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    white-space: nowrap;
    border: 1px solid transparent;
  }
  .plan-badge.pop { 
    background: rgba(79, 70, 229, 0.1); 
    color: #4338ca;
    border-color: rgba(79, 70, 229, 0.2);
  }
  .plan-badge.rec { 
    background: rgba(30, 41, 59, 0.1); 
    color: var(--slate-800);
    border-color: rgba(30, 41, 59, 0.2);
  }
  .plan-badge.trial { 
    background: rgba(22, 163, 74, 0.1); 
    color: #15803d;
    border-color: rgba(22, 163, 74, 0.2);
  }
  .plan-desc { font-size: 0.85rem; color: var(--text-muted); min-height: 40px; margin-bottom: 20px; line-height: 1.4; }

  .price-wrap { display: flex; align-items: baseline; gap: 4px; min-height: 44px; }
  .currency { font-size: 0.9rem; font-weight: 600; color: var(--text-muted); }
  .amount { font-size: 2rem; font-weight: 800; transition: opacity 0.2s; }
  .billed-text { font-size: 0.75rem; color: var(--text-muted); margin-bottom: 24px; height: 16px; }

  /* Features */
  .features-list { list-style: none; padding: 0; margin: 0 0 24px 0; flex-grow: 1; }
  .feature-item {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    font-size: 0.82rem;
    margin-bottom: 12px;
  }
  .icon-check {
    color: var(--blue-600);
    flex-shrink: 0;
    width: 16px;
    margin-top: 2px;
  }
  .feature-text { color: #475569; }
  .feature-text strong { color: #1e293b; }

