  .addon-cell {
    display: inline-block;
    font-size: .72rem;
    font-weight: 700;
    letter-spacing: .04em;
    text-transform: uppercase;
    color: #4338ca;
    background: #e0e7ff;
    border-radius: 999px;
    padding: .2rem .55rem;
  }

  /* --- Add-on strip (below the plan cards) --------------------------- */
  .addon-strip {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.5rem;
    align-items: center;
    border: 1px solid #e2e8f0;
    border-radius: 18px;
    padding: 1.75rem;
    margin: 0 0 4rem;
    background: linear-gradient(135deg, #fbfcff 0%, #f5f3ff 100%);
  }
