  .btn-outline:hover { background: #f8fafc; border-color: #94a3b8; }
  .btn-primary { background: var(--blue-600); color: white; border: 1px solid var(--blue-600); }
  .btn-primary:hover { background: var(--blue-700); }

  /* Green Button for Current Plan */
  .btn-success { background: var(--green-600); color: white; border: 1px solid var(--green-600); }

  .btn-dark { background: var(--slate-800); color: white; border: 1px solid var(--slate-800); }
  .btn-dark:hover { background: var(--slate-900); }
  .btn-white { background: white; color: var(--slate-900); border: 1px solid white; }
  .btn-white:hover { background: var(--blue-50); }

  /* Comparison Table */
  .comparison-section {
    background: white;
    border: 1px solid var(--border);
    border-radius: 16px;
