    overflow: hidden;
    margin-top: 64px;
  }
  .comp-header { padding: 30px 30px 10px; }
  .comp-header h2 { margin: 0; font-size: 1.5rem; }

  .table-scroll {
    overflow-x: auto;
    padding-bottom: 10px;
    -webkit-overflow-scrolling: touch;
  }

  .comp-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    min-width: 900px;
  }
  .comp-table th, .comp-table td {
    padding: 14px 16px;
    border-bottom: 1px solid var(--border);
    font-size: 0.85rem;
    color: var(--slate-800);
    background: white;
    vertical-align: middle;
  }
  .comp-table th {
    font-weight: 700;
    text-transform: uppercase;
    color: var(--text-muted);
    font-size: 0.75rem;
    border-bottom: 2px solid var(--border);
  }
  .comp-table th:first-child, .comp-table td:first-child {
    position: sticky;
    left: 0;
    z-index: 20;
    background: #fff;
    border-right: 1px solid var(--border);
    width: 180px;
    min-width: 180px;
  }
  .comp-table th:not(:first-child), .comp-table td:not(:first-child) { text-align: center; }
  .comp-table tr:last-child td { border-bottom: none; }

  .check-icon { color: #22c55e; }
  .dash-icon { color: #94a3b8; }

  /* Responsive */
  @media (max-width: 640px) {
    .pricing-controls {
      flex-direction: column;
      gap: 16px;
      padding: 20px;
      border-radius: 24px;
      width: 100%;
      max-width: 320px;
    }
    .control-divider {
      width: 100%;
      height: 1px;
    }
  }
  /* Current Plan Highlight */
  .price-card.current-plan {
    border: 2px solid var(--green-600);
    background: var(--green-50);
    position: relative;
  }
  /* Custom keeps dark background but gets green border */
  .price-card.custom.current-plan {
    background: var(--slate-900);
  }
  /* Current plan badge - inline style */
  .plan-badge.current {
    background: rgba(22, 163, 74, 0.15);
