  }
  .plan-badge.rec { 
    background: rgba(30, 41, 59, 0.1); 
    color: var(--slate-800);
    border-color: rgba(30, 41, 59, 0.2);
  }
  .plan-badge.trial { 
    background: rgba(22, 163, 74, 0.1); 
    color: #15803d;
    border-color: rgba(22, 163, 74, 0.2);
  }
  .plan-desc { font-size: 0.85rem; color: var(--text-muted); min-height: 40px; margin-bottom: 20px; line-height: 1.4; }

  .price-wrap { display: flex; align-items: baseline; gap: 4px; min-height: 44px; }
  .currency { font-size: 0.9rem; font-weight: 600; color: var(--text-muted); }
  .amount { font-size: 2rem; font-weight: 800; transition: opacity 0.2s; }
  .billed-text { font-size: 0.75rem; color: var(--text-muted); margin-bottom: 24px; height: 16px; }

  /* Features */
  .features-list { list-style: none; padding: 0; margin: 0 0 24px 0; flex-grow: 1; }
  .feature-item {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    font-size: 0.82rem;
    margin-bottom: 12px;
  }
  .icon-check {
    color: var(--blue-600);
