    width: 16px;
    margin-top: 2px;
  }
  .feature-text { color: #475569; }
  .feature-text strong { color: #1e293b; }

  /* Buttons */
  .addon-cell {
    display: inline-block;
    font-size: .72rem;
    font-weight: 700;
