function toggleSelectAll() {
  const selectAll = document.getElementById('select-all');
  const checkboxes = document.querySelectorAll('.invoice-checkbox');
  checkboxes.forEach(cb => cb.checked = selectAll.checked);
  updateBulkBtn();
}

function updateBulkBtn() {
  const checked = document.querySelectorAll('.invoice-checkbox:checked');
  const btn = document.getElementById('bulk-delete-btn');
  const count = document.getElementById('selected-count');

  if (checked.length > 0) {
    btn.classList.remove('d-none');
    count.textContent = checked.length;
  } else {
    btn.classList.add('d-none');
  }

  // Update select-all state
  const all = document.querySelectorAll('.invoice-checkbox');
  const selectAll = document.getElementById('select-all');
  selectAll.checked = checked.length === all.length && all.length > 0;
  selectAll.indeterminate = checked.length > 0 && checked.length < all.length;
}

async function deleteInvoice(invoiceId, btn) {
  const result = await Swal.fire({
    title: 'Delete Invoice?',
    html: '<p style="color:#6b7280;font-size:14px;">This invoice will be permanently deleted.<br>This action <strong>cannot be undone</strong>.</p>',
    icon: 'warning',
    iconColor: '#ef4444',
    showCancelButton: true,
    confirmButtonText: '<i class="fas fa-trash"></i> Yes, Delete',
    cancelButtonText: 'Cancel',
    customClass: { confirmButton: 'swal-inv-danger', cancelButton: 'swal-inv-cancel' },
    buttonsStyling: false,
  });
  if (!result.isConfirmed) return;

  const originalHtml = btn.innerHTML;
  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
  btn.disabled = true;

  try {
    const response = await fetch(`/billing/invoices/${invoiceId}/delete/`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRFToken': getCsrfToken()
      }
    });

    if (response.ok) {
      const row = btn.closest('tr');
      row.style.opacity = '0';
      row.style.transform = 'translateX(-10px)';
      row.style.transition = 'all 0.2s';
      setTimeout(() => row.remove(), 200);
    } else {
      Swal.fire('Error', 'Failed to delete invoice', 'error');
      btn.innerHTML = originalHtml;
      btn.disabled = false;
    }
  } catch (e) {
    Swal.fire('Error', e.message, 'error');
    btn.innerHTML = originalHtml;
    btn.disabled = false;
  }
}

async function bulkDeleteInvoices() {
  const checked = document.querySelectorAll('.invoice-checkbox:checked');
  const ids = Array.from(checked).map(cb => cb.dataset.id);

  if (ids.length === 0) return;

  const result = await Swal.fire({
    title: `Delete ${ids.length} Invoice${ids.length > 1 ? 's' : ''}?`,
    html: `<p style="color:#6b7280;font-size:14px;">This will permanently delete <strong>${ids.length}</strong> invoice${ids.length > 1 ? 's' : ''}. This action <strong>cannot be undone</strong>.</p>`,
    icon: 'warning',
    iconColor: '#ef4444',
    showCancelButton: true,
    confirmButtonText: `<i class="fas fa-trash"></i> Delete ${ids.length} Invoice${ids.length > 1 ? 's' : ''}`,
    cancelButtonText: 'Cancel',
    customClass: { confirmButton: 'swal-inv-danger', cancelButton: 'swal-inv-cancel' },
    buttonsStyling: false,
  });
  if (!result.isConfirmed) return;

  const btn = document.getElementById('bulk-delete-btn');
  btn.innerHTML = '<i class="fas fa-spinner fa-spin me-1"></i>Deleting...';
  btn.disabled = true;

  try {
    const response = await fetch('/billing/invoices/bulk-delete/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-CSRFToken': getCsrfToken()
      },
      body: JSON.stringify({ invoice_ids: ids })
    });

    if (response.ok) {
      ids.forEach(id => {
        const row = document.querySelector(`tr[data-invoice-id="${id}"]`);
        if (row) row.remove();
      });
      btn.classList.add('d-none');
      btn.innerHTML = '<i class="fas fa-trash me-1"></i>Delete (<span id="selected-count">0</span>)';
      btn.disabled = false;
      Swal.fire({ title: 'Deleted!', text: `${ids.length} invoice${ids.length > 1 ? 's' : ''} deleted.`, icon: 'success', timer: 1500, showConfirmButton: false });
    } else {
      Swal.fire('Error', 'Failed to delete invoices', 'error');
      btn.innerHTML = '<i class="fas fa-trash me-1"></i>Delete (<span id="selected-count">' + ids.length + '</span>)';
      btn.disabled = false;
    }
  } catch (e) {
    Swal.fire('Error', e.message, 'error');
    btn.innerHTML = '<i class="fas fa-trash me-1"></i>Delete (<span id="selected-count">' + ids.length + '</span>)';
    btn.disabled = false;
  }
}

function getCsrfToken() {
  return document.querySelector('[name=csrfmiddlewaretoken]')?.value || 
         document.cookie.split('; ').find(row => row.startsWith('csrftoken='))?.split('=')[1] || '';
