    border-radius: 32px;
    transition: all 0.5s ease;
  }
  .agent-card:hover { border-color: rgba(99, 102, 241, 0.3); }

  /* Blog cards */
  .blog-card {
    background: transparent;
    transition: all 0.4s ease;
    cursor: pointer;
  }
  .blog-card-image {
    position: relative;
    border-radius: 2.5rem;
