    width: 100%;
    height: 100%;
    object-fit: cover;
    aspect-ratio: 1/1;
    transition: transform 1s ease;
  }
  .blog-card:hover .blog-card-image img {
    transform: scale(1.08);
  }
  .blog-card-category {
    position: absolute;
    top: 1.5rem;
    left: 1.5rem;
    padding: 0.5rem 1.25rem;
