    transform: scale(0.98);
  }
  .user-avatar-nav {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, #6366f1, #8b5cf6);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: 700;
    font-size: 0.9rem;
  }
  /* Mobile menu toggle */
  .mobile-menu-toggle {
    display: none;
    width: 44px;
    height: 44px;
    background: transparent;
    border: none;
    cursor: pointer;
    padding: 0;
    z-index: 1001;
  }
  .mobile-menu-toggle span {
    display: block;
    width: 24px;
    height: 2px;
    background: #0f172a;
    margin: 5px auto;
    transition: all 0.3s ease;
    border-radius: 2px;
  }
  .mobile-menu-toggle.active span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
  }
  .mobile-menu-toggle.active span:nth-child(2) {
    opacity: 0;
  }
  .mobile-menu-toggle.active span:nth-child(3) {
    transform: rotate(-45deg) translate(5px, -5px);
  }

  /* Mobile menu overlay */
  .mobile-menu-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 255, 255, 0.98);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    z-index: 999;
    padding: 100px 2rem 2rem;
    flex-direction: column;
    align-items: center;
    gap: 1rem;
  }
  .mobile-menu-overlay.active {
    display: flex;
  }
  .mobile-menu-overlay a {
    font-size: 1.1rem;
    font-weight: 700;
    color: #0f172a;
    text-decoration: none;
    padding: 1rem 2rem;
    transition: color 0.2s;
  }
  .mobile-menu-overlay a:hover {
    color: #6366f1;
  }
  .mobile-menu-overlay .nav-cta {
    margin-top: 1rem;
    padding: 1rem 2.5rem;
    font-size: 0.85rem;
    background: linear-gradient(135deg, #6366f1, #8b5cf6);
    color: white !important;
    border-radius: 12px;
    box-shadow: 0 4px 15px rgba(99, 102, 241, 0.4);
  }
  .mobile-menu-overlay .nav-cta:hover {
    color: white !important;
    transform: scale(1.02);
  }

  @media (max-width: 991px) {
    .nav-links { display: none; }
  }

  @media (max-width: 768px) {
    .nav-login { display: none; }
    .mobile-menu-toggle { display: block; }
    .custom-navbar-inner {
      padding: 0.75rem 1rem;
    }
    .nav-brand img {
      height: 32px !important;
    }
    .nav-cta {
      padding: 0.6rem 1rem;
      font-size: 0.6rem;
      letter-spacing: 0.1em;
    }
    .nav-actions {
      gap: 0.75rem;
    }
    .hero-section {
      min-height: auto;
      padding-top: 80px !important;
    }
  }

  @media (max-width: 480px) {
    .custom-navbar-inner {
      padding: 0.5rem 0.75rem;
    }
    .nav-brand img {
      height: 28px !important;
    }
    .nav-cta {
      padding: 0.5rem 0.75rem;
      font-size: 0.55rem;
    }
  }

  /* Global overflow fix for mobile */
  html, body {
    overflow-x: hidden;
  }

  /* Dashboard visual mobile responsive */
  @media (max-width: 768px) {
    .dashboard-visual {
      transform: none !important;
      margin: 0 -0.5rem;
    }
    .dashboard-visual:hover {
      transform: none !important;
    }
    .reveal.mx-auto {
      padding: 0 0.5rem;
      max-width: 100% !important;
    }
    /* Contain overflow from floating card */
    .reveal.mx-auto > .position-relative {
      overflow: hidden;
    }
  }


  @media (max-width: 576px) {
    .dashboard-visual {
      padding: 0.75rem !important;
      margin: 0 -1rem;
    }
    .dashboard-visual .bg-white.rounded-4 {
      padding: 1rem !important;
    }
    .dashboard-visual .row.g-4 {
      --bs-gutter-x: 0.75rem;
      --bs-gutter-y: 0.75rem;
    }
    .dashboard-visual .col-md-5,
    .dashboard-visual .col-md-7 {
      padding: 0 0.5rem;
    }
    .dashboard-visual .neo-inset {
      padding: 0.75rem !important;
    }
    .dashboard-visual .font-display.fw-bold.fs-3 {
      font-size: 1.25rem !important;
    }
    .dashboard-visual .bg-light.rounded-4 {
      padding: 1rem !important;
    }
    .dashboard-visual .bg-white.rounded-3.shadow-sm {
      padding: 0.75rem !important;
    }
    .dashboard-visual .font-display.fw-bold.text-primary.fs-4,
    .dashboard-visual .font-display.fw-bold.text-success.fs-4 {
      font-size: 1.1rem !important;
    }
  }

  /* Hero background grid */
  .hero-section {
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.02) 0%, rgba(139, 92, 246, 0.04) 100%);
    min-height: 90vh;
    position: relative;
    overflow: hidden;
  }
  .hero-section::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 1000px;
    height: 1000px;
    background: radial-gradient(circle, rgba(99, 102, 241, 0.05), transparent 60%);
    border-radius: 50%;
    z-index: 0;
  }

  /* Perspective grid */
  .perspective-grid {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    perspective: 1000px;
    overflow: hidden;
    z-index: -1;
  }
  .grid-lines {
    position: absolute;
    width: 200%;
    height: 200%;
    top: -50%;
    left: -50%;
    background-image: 
      linear-gradient(to right, rgba(99, 102, 241, 0.03) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(99, 102, 241, 0.03) 1px, transparent 1px);
    background-size: 60px 60px;
    transform: rotateX(60deg);
    mask-image: radial-gradient(circle at center, black, transparent 80%);
  }

  /* Glassmorphism */
  .glass {
    background: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.6);
  }

  /* Badge */
  .badge-glow {
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(99, 102, 241, 0.15);
    box-shadow: 0 4px 20px rgba(99, 102, 241, 0.08);
  }

  /* Pulse dot */
  .pulse-dot { animation: pulse-anim 2s ease-in-out infinite; }
  @keyframes pulse-anim {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(1.5); }
  }

  /* Neo inset shadow */
  .neo-inset {
    box-shadow: inset 4px 4px 10px rgba(0,0,0,0.03), inset -4px -4px 10px rgba(255,255,255,1);
  }

  /* Dashboard visual */
  .dashboard-visual {
    transform: perspective(1000px) rotateX(8deg) rotateY(-4deg);
    transition: transform 0.8s ease;
  }
  .dashboard-visual:hover {
    transform: perspective(1000px) rotateX(0) rotateY(0);
  }

  /* Floating animation */
  @keyframes float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-15px); }
  }
  .animate-float { animation: float 6s ease-in-out infinite; }

  /* Value cards */
  .value-card {
    background: white;
    border-radius: 32px;
    border: 2px solid #f1f5f9;
    transition: all 0.4s ease;
  }
  .value-card:hover {
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.1);
    border-color: #c7d2fe;
    transform: translateY(-4px);
  }
  .value-card .value-icon {
    display: inline-block;
    transition: transform 0.4s ease;
  }
  .value-card:hover .value-icon {
    transform: scale(1.25);
  }

  /* Feature cards */
  .feature-card-new {
    background: white;
    border-radius: 24px;
    border: 1px solid #f1f5f9;
    transition: all 0.4s ease;
    position: relative;
    overflow: hidden;
  }
  .feature-card-new::after {
    content: '';
    position: absolute;
    top: 0; right: 0;
    width: 100px; height: 100px;
    background: #f8fafc;
    border-radius: 0 0 0 100px;
    z-index: 0;
    transition: background 0.3s;
  }
  .feature-card-new:hover {
    transform: translateY(-8px);
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.1);
  }
  .feature-card-new:hover::after { background: rgba(99, 102, 241, 0.05); }

  /* Dark section */
  .dark-section {
    background: #0f172a;
    position: relative;
  }
  .dark-section::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(circle at 70% 50%, rgba(99, 102, 241, 0.1), transparent 50%),
                radial-gradient(circle at 20% 80%, rgba(168, 85, 247, 0.08), transparent 50%);
  }

  /* Agent config cards */
  .agent-card {
    background: rgba(30, 41, 59, 0.4);
    backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 32px;
    transition: all 0.5s ease;
  }
  .agent-card:hover { border-color: rgba(99, 102, 241, 0.3); }

  /* Blog cards */
  .blog-card {
    background: transparent;
    transition: all 0.4s ease;
    cursor: pointer;
  }
  .blog-card-image {
    position: relative;
    border-radius: 2.5rem;
    overflow: hidden;
    margin-bottom: 1.5rem;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.05);
    transition: all 0.5s ease;
  }
  .blog-card:hover .blog-card-image {
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.15);
  }
  .blog-card-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    aspect-ratio: 1/1;
    transition: transform 1s ease;
  }
  .blog-card:hover .blog-card-image img {
    transform: scale(1.08);
  }
  .blog-card-category {
    position: absolute;
    top: 1.5rem;
    left: 1.5rem;
    padding: 0.5rem 1.25rem;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    border-radius: 100px;
    font-size: 0.65rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #0f172a;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
  }
  .blog-card-arrow {
    position: absolute;
    bottom: 1.5rem;
    right: 1.5rem;
    width: 56px;
    height: 56px;
    background: #0f172a;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    transform: translateY(20px);
    opacity: 0;
    transition: all 0.5s ease;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  }
  .blog-card:hover .blog-card-arrow {
    transform: translateY(0);
    opacity: 1;
  }
  .blog-card-title {
    font-size: 1.5rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.3;
    margin-bottom: 0.75rem;
    transition: color 0.3s ease;
  }
  .blog-card:hover .blog-card-title {
    color: #6366f1;
  }
  .blog-card-excerpt {
    color: #64748b;
    font-size: 1rem;
    line-height: 1.7;
    font-weight: 500;
  }

  /* Newsletter */
  .newsletter-section {
    background: linear-gradient(135deg, #6366f1 0%, #7c3aed 100%);
    border-radius: 48px;
    position: relative;
    overflow: hidden;
  }
  .newsletter-section::before {
    content: '';
    position: absolute;
    top: -50%; right: -50%;
    width: 100%; height: 100%;
    background: radial-gradient(circle, rgba(255,255,255,0.1), transparent 50%);
  }

  /* FAQ */
  .faq-item {
    background: white;
    border-radius: 32px;
    border: 1px solid #f1f5f9;
    transition: all 0.3s ease;
    box-shadow: 0 2px 8px rgba(0,0,0,0.02);
  }
  .faq-item:hover {
    border-color: #e2e8f0;
    box-shadow: 0 15px 40px rgba(0,0,0,0.08);
  }
  .faq-item.active {
    border-color: rgba(99, 102, 241, 0.3);
    box-shadow: 0 15px 40px rgba(99,102,241,0.1);
  }
  .faq-trigger {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 2rem;
    cursor: pointer;
    background: transparent;
    width: 100%;
    border: none;
    text-align: left;
  }
  .faq-question {
    font-size: 1.2rem;
    font-weight: 700;
    color: #0f172a;
    transition: color 0.3s;
    padding-right: 1rem;
  }
  .faq-item:hover .faq-question,
  .faq-item.active .faq-question {
    color: #6366f1;
  }
  .faq-icon {
    width: 40px;
    height: 40px;
    min-width: 40px;
    border-radius: 50%;
    background: #f1f5f9;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.5s ease;
  }
  .faq-icon svg {
    width: 20px;
    height: 20px;
    stroke: #64748b;
    transition: stroke 0.3s;
  }
  .faq-item:hover .faq-icon {
    background: rgba(99, 102, 241, 0.1);
  }
  .faq-item:hover .faq-icon svg {
    stroke: #6366f1;
  }
  .faq-item.active .faq-icon {
    background: #6366f1;
    transform: rotate(180deg);
  }
  .faq-item.active .faq-icon svg {
    stroke: white;
  }
  .faq-content {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 0.5s ease;
  }
  .faq-content-inner {
    overflow: hidden;
    min-height: 0;
  }
  .faq-item.active .faq-content {
    grid-template-rows: 1fr;
  }

  /* CTA */
  .cta-dark {
    background: #0f172a;
    border-radius: 48px;
    position: relative;
    overflow: hidden;
  }
  .cta-dark::before {
    content: '';
    position: absolute;
    top: -50%; left: -50%;
    width: 200%; height: 200%;
    background: radial-gradient(circle at center, rgba(99, 102, 241, 0.15), transparent 50%);
    animation: pulse-anim 4s ease-in-out infinite;
  }

  /* Marquee */
  .marquee-container { overflow: hidden; }
  .marquee-track {
    display: flex;
    animation: marquee 30s linear infinite;
    width: max-content;
  }
  @keyframes marquee { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } }
  .marquee-item {
    font-family: 'Outfit', sans-serif;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.05em;
    color: #e2e8f0;
    padding: 0 3rem;
    white-space: nowrap;
  }

  /* Reveal */
  .reveal {
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.8s ease, transform 0.8s ease;
  }
