    /* Anti-FOUC: hide the workspace until stylesheets are applied, so the page
       never paints as raw unstyled HTML for a frame. Uses visibility (no reflow)
       and is applied only when JS runs, so it always fails OPEN. */
    html.cai-preload .main-wrapper { visibility: hidden; } /* Runs synchronously in <head> BEFORE first paint, so the initial paint is
       already hidden. Revealed on DOMContentLoaded / load, with a hard timeout
       fail-safe so content can never get stuck hidden (JS error, slow CDN, etc.). */
    document.documentElement.classList.add('cai-preload');
    (function () {
      var shown = false;
      function reveal() {
        if (shown) return;
        shown = true;
        document.documentElement.classList.remove('cai-preload');
      }
      document.addEventListener('DOMContentLoaded', reveal);
      window.addEventListener('load', reveal);
      setTimeout(reveal, 1500);
