// Update access scope dropdown label based on selection
function updateScopeLabel() {
    const checkboxes = document.querySelectorAll('.scope-checkbox:checked');
    const label = document.getElementById('scopesBtnLabel');
    const btn = document.getElementById('accessScopesBtn');
    if (!label || !btn) return;
    if (checkboxes.length === 0) {
        label.textContent = 'Select at least one scope...';
        label.classList.add('text-secondary');
        label.classList.remove('text-dark');
    } else {
        label.textContent = checkboxes.length === 1
            ? checkboxes[0].closest('.form-check').querySelector('label').textContent.trim()
            : `${checkboxes.length} accesses selected`;
        label.classList.remove('text-secondary');
        label.classList.add('text-dark');
        btn.classList.remove('border-danger');
        // Hide error if now valid
        const err = document.getElementById('scopesError');
        if (err) err.style.display = 'none';
    }
}

document.querySelectorAll('.scope-checkbox').forEach(function(cb) {
