        border-bottom: 1px solid rgba(0, 0, 0, 0.05);
        padding: 1rem 0;
      }

      .navbar-brand-modern {
        font-family: 'Poppins', sans-serif;
        font-weight: 700;
        font-size: 1.5rem;
      }

