    function toggleSubmenu(element, event) {
      event.preventDefault();
      element.classList.toggle('open');
      var submenu = element.nextElementSibling;
      if (submenu && submenu.classList.contains('submenu')) {
        submenu.classList.toggle('open');
      }
    }

    document.addEventListener('DOMContentLoaded', function () {
      const sidebar = document.getElementById('sidebar');
      const mainContent = document.getElementById('mainContent');
      const toggleBtn = document.getElementById('sidebarToggle');
      const mobileToggle = document.getElementById('mobileMenuToggle');
      const mobileOverlay = document.getElementById('mobileOverlay');
      const toggleIcon = toggleBtn ? toggleBtn.querySelector('i') : null;

      // Function to update icon
      function updateIcon(isCollapsed) {
        if (!toggleIcon) return;
        if (isCollapsed) {
          toggleIcon.classList.remove('bi-chevron-left');
          toggleIcon.classList.add('bi-chevron-right');
        } else {
          toggleIcon.classList.remove('bi-chevron-right');
          toggleIcon.classList.add('bi-chevron-left');
        }
      }

      // Check saved state
      const isCollapsed = localStorage.getItem('sidebarCollapsed') === 'true';
      if (isCollapsed) {
        sidebar.classList.add('collapsed');
        mainContent.classList.add('expanded');
        updateIcon(true);
      }

      // Toggle click handler
      if (toggleBtn) {
        toggleBtn.addEventListener('click', function () {
          sidebar.classList.toggle('collapsed');
          mainContent.classList.toggle('expanded');

          const collapsed = sidebar.classList.contains('collapsed');
          localStorage.setItem('sidebarCollapsed', collapsed);
          updateIcon(collapsed);
        });
      }

      // Mobile menu toggle is handled by modern-script.js

      // Submenu handling
      document.querySelectorAll('.nav-item.has-submenu').forEach(function (item) {
        item.addEventListener('click', function (e) {
          e.preventDefault();
          this.classList.toggle('open');
          const submenu = this.nextElementSibling;
          if (submenu && submenu.classList.contains('submenu')) {
            submenu.classList.toggle('open');
          }
        });
      });

      // Auto-open relevant submenu based on current URL
      const currentPath = window.location.pathname;
      let foundActive = false;

      // First pass: find exact match
      document.querySelectorAll('.submenu-item').forEach(function (item) {
        const href = item.getAttribute('href');
        if (href && currentPath === href) {
          foundActive = true;
          item.classList.add('active');
          const parentSubmenu = item.closest('.submenu');
          if (parentSubmenu) {
            parentSubmenu.classList.add('open');
            const parentToggle = parentSubmenu.previousElementSibling;
            if (parentToggle) {
              parentToggle.classList.add('open');
            }
          }
        }
      });

      // Second pass: if no exact match, try normalized matching
      if (!foundActive) {
        document.querySelectorAll('.submenu-item').forEach(function (item) {
          const href = item.getAttribute('href');
          if (href) {
            // Normalize paths by removing trailing slashes for comparison
            const normalizedHref = href.replace(/\/$/, '');
            const normalizedPath = currentPath.replace(/\/$/, '');

            // Only exact match after normalization - no prefix matching
            // This prevents /knowledge/ from matching /knowledge/docs/
            if (normalizedPath === normalizedHref) {
              item.classList.add('active');
              const parentSubmenu = item.closest('.submenu');
              if (parentSubmenu) {
                parentSubmenu.classList.add('open');
                const parentToggle = parentSubmenu.previousElementSibling;
                if (parentToggle) {
                  parentToggle.classList.add('open');
                }
              }
            }
          }
        });
      }

      // Fallback: If on sales, lead-capture, or lead-engagement, highlight Agents in submenu
      if (!foundActive && (currentPath.startsWith('/sales') || currentPath.startsWith('/lead-capture') || currentPath.startsWith('/lead-engagement'))) {
        const toolsItem = document.querySelector('.submenu-item[data-page="tools"]');
        if (toolsItem) {
          toolsItem.classList.add('active');
          const parentSubmenu = toolsItem.closest('.submenu');
          if (parentSubmenu) {
            parentSubmenu.classList.add('open');
            const parentToggle = parentSubmenu.previousElementSibling;
            if (parentToggle) parentToggle.classList.add('open');
          }
        }
      }

      // Set active nav item (only for non-submenu items)
      document.querySelectorAll('.nav-item:not(.has-submenu)').forEach(function (item) {
        const href = item.getAttribute('href');
        if (href && currentPath === href) {
          item.classList.add('active');
        }
      });
